{"path": "/tmp/sv-7d09d64a3cbb483699068f816f4cb739/Components/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product list pagination">
    <button class="page-btn"
            disabled="@(Page <= 1)"
            @onclick="() => GoToPage(Page - 1)">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="page-btn @(pageNum == Page ? "active" : "")"
                @onclick="() => GoToPage(pageNum)">
            @pageNum
        </button>
    }

    <button class="page-btn"
            disabled="@(Page >= TotalPages)"
            @onclick="() => GoToPage(Page + 1)">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}
"}

