toolArgs.file_text:
h1 {
    margin: 0 0 1rem;
    font-size: 1.75rem;
    color: #111827;
}

.catalog-layout {
    display: flex;
    gap: 0;
    min-height: 80vh;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
}

::deep .catalog-filters {
    width: 25%;
    min-width: 220px;
    flex-shrink: 0;
}

.catalog-main {
    flex: 1;
    padding: 1.5rem;
    position: relative;
}

.loading-overlay {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
    color: #6b7280;
    font-size: 1rem;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
    color: #9ca3af;
    font-size: 1rem;
}

.error-banner {
    background: #fef2f2;
    border: 1px solid #fecaca;
    border-radius: 8px;
    padding: 1rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
}

.error-banner p {
    margin: 0;
    color: #dc2626;
    font-size: 0.9rem;
}

.error-banner button {
    padding: 0.4rem 1rem;
    background: #dc2626;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.875rem;
}

.error-banner button:hover {
    background: #b91c1c;
}

